{
  "name": "VXI-11通信组件",
  "name_en": "VXI-11 Communicator",
  "manufacturer": "",
  "description": "用于通过以太网 VXI-11 协议连接测试测量设备的非实体通信组件。它提供连接地址、终止符和超时等通信属性管理，并支持原始字节读写与连接关闭，适合实验系统中对支持 VXI-11 的仪器进行底层通信。",
  "description_en": "A non-physical communication component for connecting to test and measurement instruments over Ethernet using the VXI-11 protocol. It manages communication properties such as address, terminator, and timeout, and supports raw byte read/write and connection closing for low-level control of VXI-11-capable instruments in laboratory systems.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭 VXI-11 连接。",
      "description_en": "Close the VXI-11 connection."
    },
    {
      "action_name": "auto-flush_input",
      "description": "清空输入缓冲区（此组件中未实现）。",
      "description_en": "Flush the input buffer (not implemented in this component)."
    },
    {
      "action_name": "auto-read_raw",
      "description": "从 VXI-11 连接读取原始字节数据。",
      "description_en": "Read raw bytes from the VXI-11 connection."
    },
    {
      "action_name": "auto-seek",
      "description": "移动到指定输入偏移位置（此组件中未实现）。",
      "description_en": "Move to a specified input offset (not implemented in this component)."
    },
    {
      "action_name": "auto-tell",
      "description": "获取当前输入偏移位置（此组件中未实现）。",
      "description_en": "Get the current input offset (not implemented in this component)."
    },
    {
      "action_name": "auto-terminator",
      "description": "获取/设置通信终止符。",
      "description_en": "Get/set the communication terminator."
    },
    {
      "action_name": "auto-timeout",
      "description": "获取/设置通信超时时间。",
      "description_en": "Get/set the communication timeout."
    },
    {
      "action_name": "auto-write_raw",
      "description": "向 VXI-11 连接写入原始字节数据。",
      "description_en": "Write raw bytes to the VXI-11 connection."
    },
    {
      "action_name": "auto-address",
      "description": "获取连接主机地址和设备名。",
      "description_en": "Get the connection host address and instrument name."
    }
  ],
  "tag_hints": [
    "VXI-11 communication",
    "Ethernet instrument control",
    "test and measurement connectivity",
    "raw byte I/O",
    "instrument session settings",
    "timeout configuration",
    "terminator handling"
  ]
}

